-- SOV Oružarstvo v6.1.5c — XLS CANONICAL ARMORY / INVENTORY FIX
-- Generated: 2026-06-03 hotfix for Supabase temp-table scope + safe views + duplicate names
-- Source XLS: SOV_oruzarstvo_jednostavna_popunjena_evidencija.xlsx, sheet "SOV oruzarstvo evidencija"
--
-- Goal:
--   1) Make the database match the XLS exactly: 551 rows, 12 XLS categories.
--   2) Stop automatic category remapping / merging.
--   3) Preserve rows with empty quantity as "za provjeru" instead of making them requestable.
--   4) Keep request/loan history. Only old XLS-derived equipment_items rows are replaced.
--   5) v6.1.5a: idempotent category/location seeding for existing databases with unique name constraints.
--   6) v6.1.5c: drop/recreate app catalog views safely because old view column names differ.

begin;

create extension if not exists pgcrypto;

create table if not exists public.equipment_categories (
  id uuid primary key default gen_random_uuid(),
  legacy_id text unique,
  name text not null,
  description text,
  type text,
  sort_order integer,
  updated_at timestamptz not null default now()
);

create table if not exists public.equipment_locations (
  id uuid primary key default gen_random_uuid(),
  legacy_id text unique,
  name text not null,
  description text,
  type text
);

alter table public.equipment_categories
  add column if not exists legacy_id text,
  add column if not exists name text,
  add column if not exists description text,
  add column if not exists type text,
  add column if not exists sort_order integer,
  add column if not exists updated_at timestamptz not null default now();

create unique index if not exists equipment_categories_legacy_id_uq on public.equipment_categories(legacy_id);

alter table public.equipment_locations
  add column if not exists legacy_id text,
  add column if not exists name text,
  add column if not exists description text,
  add column if not exists type text;

create unique index if not exists equipment_locations_legacy_id_uq on public.equipment_locations(legacy_id);

create table if not exists public.equipment_items (
  id uuid primary key default gen_random_uuid(),
  legacy_id text unique,
  catalog_id text,
  name text not null,
  category_id text,
  category_name text,
  subcategory text,
  unit text default 'kom',
  tracking_type text,
  quantity numeric default 0,
  loaned numeric default 0,
  available numeric default 0,
  minimum numeric,
  status text default 'aktivno',
  availability text default 'dostupno',
  member_visible boolean not null default true,
  internal_note text,
  source_sheet text,
  item_kind text,
  code_required boolean not null default false,
  physical_code_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.equipment_items
  add column if not exists catalog_id text,
  add column if not exists category_id text,
  add column if not exists category_name text,
  add column if not exists subcategory text,
  add column if not exists unit text default 'kom',
  add column if not exists tracking_type text,
  add column if not exists quantity numeric default 0,
  add column if not exists loaned numeric default 0,
  add column if not exists available numeric default 0,
  add column if not exists minimum numeric,
  add column if not exists status text default 'aktivno',
  add column if not exists availability text default 'dostupno',
  add column if not exists member_visible boolean not null default true,
  add column if not exists internal_note text,
  add column if not exists location_name text default 'Oružarstvo',
  add column if not exists source_sheet text,
  add column if not exists item_kind text,
  add column if not exists code_required boolean not null default false,
  add column if not exists physical_code_note text,
  add column if not exists quantity_label text,
  add column if not exists available_label text,
  add column if not exists last_inventory_date date,
  add column if not exists source_xls_row integer,
  add column if not exists xls_category text,
  add column if not exists xls_subcategory text,
  add column if not exists original_quantity_text text,
  add column if not exists created_at timestamptz not null default now(),
  add column if not exists updated_at timestamptz not null default now();

create unique index if not exists equipment_items_legacy_id_uq on public.equipment_items(legacy_id);
create index if not exists equipment_items_xls_source_idx on public.equipment_items(source_sheet);
create index if not exists equipment_items_category_idx on public.equipment_items(category_name, subcategory);
create index if not exists equipment_items_search_idx on public.equipment_items using gin (to_tsvector('simple', coalesce(name,'') || ' ' || coalesce(category_name,'') || ' ' || coalesce(subcategory,'') || ' ' || coalesce(internal_note,'')));

-- Replace only previous XLS-derived seed rows. This does not delete requests/loans/history.
delete from public.equipment_items
where coalesce(source_sheet,'') ilike '%SOV_oruzarstvo_jednostavna_popunjena_evidencija%';

-- Preserve existing category rows and attach canonical XLS metadata by NAME.
-- v6.1.5c: no temporary tables / CTE leakage. Supabase SQL editor can run this as one plain script.
with xls_categories(legacy_id,name,description,type,sort_order,updated_at) as (
  values
  ('CAT-osobna-oprema','Osobna oprema','XLS kategorija: Osobna oprema (15 stavki)','xls',10,now()),('CAT-oprema-za-postavljanje','Oprema za postavljanje','XLS kategorija: Oprema za postavljanje (56 stavki)','xls',20,now()),('CAT-cisto-podzemlje','Čisto podzemlje','XLS kategorija: Čisto podzemlje (19 stavki)','xls',30,now()),('CAT-oprema-za-crtanje','Oprema za crtanje','XLS kategorija: Oprema za crtanje (14 stavki)','xls',40,now()),('CAT-oprema-za-prosirivanje','Oprema za proširivanje','XLS kategorija: Oprema za proširivanje (45 stavki)','xls',50,now()),('CAT-elektro-i-foto-oprema','Elektro i foto oprema','XLS kategorija: Elektro i foto oprema (39 stavki)','xls',60,now()),('CAT-alpinisticka-oprema','Alpinistička oprema','XLS kategorija: Alpinistička oprema (23 stavki)','xls',70,now()),('CAT-ronilacka-oprema','Ronilačka oprema','XLS kategorija: Ronilačka oprema (8 stavki)','xls',80,now()),('CAT-ostali-alat','Ostali alat','XLS kategorija: Ostali alat (39 stavki)','xls',90,now()),('CAT-uzeta','Užeta','XLS kategorija: Užeta (26 stavki)','xls',100,now()),('CAT-oprema-za-logor','Oprema za logor','XLS kategorija: Oprema za logor (202 stavki)','xls',110,now()),('CAT-medicinska-oprema','Medicinska oprema','XLS kategorija: Medicinska oprema (65 stavki)','xls',120,now())
)
update public.equipment_categories ec
   set legacy_id = null,
       updated_at = now()
  from xls_categories c
 where ec.legacy_id = c.legacy_id
   and ec.name is distinct from c.name;

with xls_categories(legacy_id,name,description,type,sort_order,updated_at) as (
  values
  ('CAT-osobna-oprema','Osobna oprema','XLS kategorija: Osobna oprema (15 stavki)','xls',10,now()),('CAT-oprema-za-postavljanje','Oprema za postavljanje','XLS kategorija: Oprema za postavljanje (56 stavki)','xls',20,now()),('CAT-cisto-podzemlje','Čisto podzemlje','XLS kategorija: Čisto podzemlje (19 stavki)','xls',30,now()),('CAT-oprema-za-crtanje','Oprema za crtanje','XLS kategorija: Oprema za crtanje (14 stavki)','xls',40,now()),('CAT-oprema-za-prosirivanje','Oprema za proširivanje','XLS kategorija: Oprema za proširivanje (45 stavki)','xls',50,now()),('CAT-elektro-i-foto-oprema','Elektro i foto oprema','XLS kategorija: Elektro i foto oprema (39 stavki)','xls',60,now()),('CAT-alpinisticka-oprema','Alpinistička oprema','XLS kategorija: Alpinistička oprema (23 stavki)','xls',70,now()),('CAT-ronilacka-oprema','Ronilačka oprema','XLS kategorija: Ronilačka oprema (8 stavki)','xls',80,now()),('CAT-ostali-alat','Ostali alat','XLS kategorija: Ostali alat (39 stavki)','xls',90,now()),('CAT-uzeta','Užeta','XLS kategorija: Užeta (26 stavki)','xls',100,now()),('CAT-oprema-za-logor','Oprema za logor','XLS kategorija: Oprema za logor (202 stavki)','xls',110,now()),('CAT-medicinska-oprema','Medicinska oprema','XLS kategorija: Medicinska oprema (65 stavki)','xls',120,now())
)
update public.equipment_categories ec
   set legacy_id = c.legacy_id,
       description = c.description,
       type = c.type,
       sort_order = c.sort_order,
       updated_at = now()
  from xls_categories c
 where ec.name = c.name;

with xls_categories(legacy_id,name,description,type,sort_order,updated_at) as (
  values
  ('CAT-osobna-oprema','Osobna oprema','XLS kategorija: Osobna oprema (15 stavki)','xls',10,now()),('CAT-oprema-za-postavljanje','Oprema za postavljanje','XLS kategorija: Oprema za postavljanje (56 stavki)','xls',20,now()),('CAT-cisto-podzemlje','Čisto podzemlje','XLS kategorija: Čisto podzemlje (19 stavki)','xls',30,now()),('CAT-oprema-za-crtanje','Oprema za crtanje','XLS kategorija: Oprema za crtanje (14 stavki)','xls',40,now()),('CAT-oprema-za-prosirivanje','Oprema za proširivanje','XLS kategorija: Oprema za proširivanje (45 stavki)','xls',50,now()),('CAT-elektro-i-foto-oprema','Elektro i foto oprema','XLS kategorija: Elektro i foto oprema (39 stavki)','xls',60,now()),('CAT-alpinisticka-oprema','Alpinistička oprema','XLS kategorija: Alpinistička oprema (23 stavki)','xls',70,now()),('CAT-ronilacka-oprema','Ronilačka oprema','XLS kategorija: Ronilačka oprema (8 stavki)','xls',80,now()),('CAT-ostali-alat','Ostali alat','XLS kategorija: Ostali alat (39 stavki)','xls',90,now()),('CAT-uzeta','Užeta','XLS kategorija: Užeta (26 stavki)','xls',100,now()),('CAT-oprema-za-logor','Oprema za logor','XLS kategorija: Oprema za logor (202 stavki)','xls',110,now()),('CAT-medicinska-oprema','Medicinska oprema','XLS kategorija: Medicinska oprema (65 stavki)','xls',120,now())
)
select c.legacy_id,c.name,c.description,c.type,c.sort_order,now()
  from xls_categories c
 where not exists (
   select 1 from public.equipment_categories ec where ec.name = c.name
 )
on conflict (legacy_id) do update set
  name=excluded.name,
  description=excluded.description,
  type=excluded.type,
  sort_order=excluded.sort_order,
  updated_at=now();

