-- Exact XLS taxonomy. Do not infer new buckets from names.
create or replace function public.sov_armory_main_category(raw_category text, search_basis text default null)
returns text
language sql
immutable
as $$
  select case
    when trim(coalesce(raw_category,'')) = 'Užad' then 'Užeta'
    when nullif(trim(coalesce(raw_category,'')), '') is not null then trim(raw_category)
    else 'Ostalo'
  end
$$;

create or replace function public.sov_armory_category_priority(category text)
returns int
language sql
immutable
as $$
  select case public.sov_armory_main_category(category, category)
    when 'Osobna oprema' then 10 when 'Oprema za postavljanje' then 20 when 'Čisto podzemlje' then 30 when 'Oprema za crtanje' then 40 when 'Oprema za proširivanje' then 50 when 'Elektro i foto oprema' then 60 when 'Alpinistička oprema' then 70 when 'Ronilačka oprema' then 80 when 'Ostali alat' then 90 when 'Užeta' then 100 when 'Oprema za logor' then 110 when 'Medicinska oprema' then 120
    else 999
  end
$$;

create or replace function public.sov_armory_search_tags(main_category text, subcategory text, search_basis text)
returns text
language sql
immutable
as $$
  select concat_ws(' ', main_category, subcategory, search_basis)
$$;

-- Existing production databases may already have these views with a different
-- column order/name set. PostgreSQL cannot CREATE OR REPLACE a view when that
-- would rename an existing output column, so rebuild the view definitions.
drop view if exists public.sov_equipment_app_catalog_grouped cascade;
drop view if exists public.sov_equipment_app_catalog cascade;

create or replace view public.sov_equipment_app_catalog as
select
  'item:' || e.legacy_id as app_id,
  'equipment_items'::text as source_table,
  e.legacy_id as source_id,
  e.legacy_id,
  e.catalog_id,
  null::text as code,
  e.name,
  e.category_name as raw_category,
  e.subcategory as raw_subcategory,
  public.sov_armory_main_category(e.category_name, e.name) as main_category,
  coalesce(nullif(e.subcategory,''),'Ostalo') as subcategory,
  coalesce(nullif(e.location_name,''),'Oružarstvo') as location_name,
  coalesce(e.quantity,0) as total_qty,
  coalesce(e.available,0) as available_qty,
  coalesce(e.unit,'kom') as unit,
  e.status,
  e.availability,
  coalesce(e.member_visible,true) as member_visible,
  e.internal_note as note,
  e.internal_note as detail_summary,
  e.physical_code_note,
  e.quantity_label,
  e.available_label,
  e.last_inventory_date,
  e.source_xls_row,
  e.xls_category,
  e.xls_subcategory,
  e.original_quantity_text,
  e.item_kind,
  public.sov_armory_category_priority(e.category_name) as priority,
  concat_ws(' ', e.name, e.category_name, e.subcategory, e.internal_note, e.physical_code_note, e.original_quantity_text) as search_text,
  e.updated_at
from public.equipment_items e
where coalesce(e.member_visible,true)
  and lower(coalesce(e.status,'')) !~ '(rashod|otpis|deleted|obrisano|arhiva|stari_katalog|neaktiv)';

create or replace view public.sov_equipment_app_catalog_grouped as
select
  app_id,
  source_table,
  source_id,
  legacy_id,
  catalog_id,
  code,
  name as display_name,
  name,
  raw_category,
  raw_subcategory,
  main_category,
  subcategory,
  location_name,
  total_qty,
  available_qty,
  unit,
  status,
  availability,
  member_visible,
  note,
  detail_summary,
  physical_code_note,
  quantity_label,
  available_label,
  last_inventory_date,
  source_xls_row,
  xls_category,
  xls_subcategory,
  original_quantity_text,
  item_kind,
  priority,
  search_text,
  source_id as catalog_group_key,
  1::integer as variant_count,
  updated_at
from public.sov_equipment_app_catalog;

grant select on public.sov_equipment_app_catalog to anon, authenticated;
grant select on public.sov_equipment_app_catalog_grouped to anon, authenticated;
grant select on public.equipment_categories to anon, authenticated;
grant select on public.equipment_locations to anon, authenticated;

-- Fast manifest row used by web/APK cache invalidation.
do $$
begin
  if exists (
    select 1
    from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public' and c.relname='sov_equipment_catalog_manifest' and c.relkind='v'
  ) then
    execute 'drop view public.sov_equipment_catalog_manifest';
  end if;
end $$;

create table if not exists public.sov_equipment_catalog_manifest (
  id boolean primary key default true,
  catalog_version text not null default md5(now()::text),
  raw_row_count integer not null default 0,
  grouped_row_count integer not null default 0,
  equipment_items_count integer not null default 0,
  equipment_ropes_count integer not null default 0,
  equipment_pieces_count integer not null default 0,
  last_changed_at timestamptz not null default now(),
  requests_changed_at timestamptz not null default now(),
  checked_at timestamptz not null default now()
);

alter table public.sov_equipment_catalog_manifest disable row level security;
grant select on public.sov_equipment_catalog_manifest to anon, authenticated;

  id, catalog_version, raw_row_count, grouped_row_count,
  equipment_items_count, equipment_ropes_count, equipment_pieces_count,
  last_changed_at, requests_changed_at, checked_at
) values (
  true,
  md5('sov-armory-v6.1.5c-xls-canonical-551|' || now()::text),
  (select count(*)::int from public.sov_equipment_app_catalog),
  (select count(*)::int from public.sov_equipment_app_catalog_grouped),
  (select count(*)::int from public.equipment_items where coalesce(source_sheet,'') ilike '%SOV_oruzarstvo_jednostavna_popunjena_evidencija%'),
  0,
  0,
  now(),
  now(),
  now()
)
on conflict (id) do update set
  catalog_version=excluded.catalog_version,
  raw_row_count=excluded.raw_row_count,
  grouped_row_count=excluded.grouped_row_count,
  equipment_items_count=excluded.equipment_items_count,
  equipment_ropes_count=excluded.equipment_ropes_count,
  equipment_pieces_count=excluded.equipment_pieces_count,
  last_changed_at=excluded.last_changed_at,
  checked_at=excluded.checked_at;

commit;

